package com.nthexperience.desktop;

import android.app.*;
import android.content.*;
import android.content.pm.ActivityInfo;
import android.graphics.Rect;
import android.os.*;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.lang.reflect.Field;
import java.util.concurrent.atomic.AtomicReference;

/** Real split Settings, utility destinations and composer-only local action buttons. */
public final class TenCommandsSmoke extends TenThemeSmoke {
    @Override public void onStart(){Bundle output=new Bundle();try{
        store=new DesktopStore(getTargetContext());store.prefs.edit().putInt("startup_mode",2).putBoolean("welcome_on_start",false).putBoolean("reduce_motion",true).putBoolean("taskbar_apps",false).putString("ten_nota_draft","").remove(TenDesktops.KEY).remove(TenDesktopItems.KEY).commit();TenThemes.TEN.get(0).apply(store);
        getTargetContext().getSharedPreferences("ten-nota-ai-privacy",0).edit().putBoolean("cloud-allowed",false).putInt("consent-version",1).commit();
        getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putBoolean(StartupExperience.HOME_OFFERED,true).commit();
        home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();await(()->TenSmoke.description(root,"Start menu")!=null,"Shell ready");
        settings(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT);settings(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE);utilities();commands();
        output.putString("stream","PASS: permanent full-height Settings sidebar and visible content in both orientations, narrow window and dark/light colors, calculator under tools, local Nota shortcuts without a model or cloud, Browser and Settings routing, edited suggestions, Android Wi-Fi intent, installed app launch, empty new desktop, imported passage and generated reply boundaries\n");finish(Activity.RESULT_OK,output);
    }catch(Throwable error){try{shot("ten8-failure");}catch(Exception ignored){}output.putString("stream","FAIL: "+android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,output);}}
    TenDesktops desks(){try{Field f=MainActivity.class.getDeclaredField("tenDesktops");f.setAccessible(true);return(TenDesktops)f.get(home);}catch(Exception e){throw new RuntimeException(e);}}
    void settings(int orientation)throws Exception{
        ui(()->{home.setRequestedOrientation(orientation);home.open("ten-setting:background");windows().get("@settings").maximize();});await(()->(root.getHeight()>root.getWidth())==(orientation==ActivityInfo.SCREEN_ORIENTATION_PORTRAIT),"Settings orientation");await(()->{TenSettings s=(TenSettings)windows().get("@settings").body;return s.width==s.getWidth()&&s.nav.getWidth()>0&&s.scroll.getWidth()>0;},"Split layout measured");
        ui(()->{TenSettings s=(TenSettings)windows().get("@settings").body;Rect a=new Rect(),b=new Rect();check(s.nav.getVisibility()==View.VISIBLE&&s.scroll.getVisibility()==View.VISIBLE&&s.nav.getGlobalVisibleRect(a)&&s.scroll.getGlobalVisibleRect(b)&&a.right<=b.left,"Sidebar and content are both visible side by side");check(s.nav.getHeight()==s.area.getHeight()&&s.side.getHeight()>=s.nav.getHeight(),"Gray sidebar fills all remaining height");check(s.nav.getWidth()<s.getWidth()/2&&s.scroll.getWidth()>s.nav.getWidth(),"Content keeps most of the width");check(TenSmoke.text(s.body,"Choose your background")!=null,"Page content remains visible");});shot(orientation==ActivityInfo.SCREEN_ORIENTATION_PORTRAIT?"ten8-settings-portrait":"ten8-settings-landscape");
        if(orientation==ActivityInfo.SCREEN_ORIENTATION_PORTRAIT){ui(()->{TenSettings s=(TenSettings)windows().get("@settings").body;s.scroll.scrollTo(0,150);check(s.nav.getScrollY()==0,"Independent page scroll");s.navigate("themes");check(TenSmoke.description(s,"Ten theme gallery")!=null,"All themes accessible beside portrait sidebar");});shot("ten8-settings-themes");}
    }
    void utilities()throws Exception{ui(()->{TenSettings s=(TenSettings)windows().get("@settings").body;s.navigate("games");check(TenSmoke.text(s.body,"Calculator")==null&&TenSmoke.text(s.body,"Tile puzzle")!=null,"Games excludes calculator");s.navigate("tools");check(TenSmoke.text(s.body,"Calculator")!=null,"Calculator is discoverable in Nth tools");home.open("@news");View games=TenSmoke.description(root,"Nth games card"),tools=TenSmoke.description(root,"Nth tools card");check(games!=null&&tools!=null&&TenSmoke.text(games,"Calculator")==null&&TenSmoke.text(tools,"Calculator")!=null,"News utility and game cards are classified consistently");home.open("@settings");});}
    TenNotaPanel panel(){return(TenNotaPanel)windows().get("@nota").body;}
    void ask(String message)throws Exception{ask(message,5);}
    void ask(String message,int mode)throws Exception{ui(()->{home.open("@nota");TenNotaPanel p=panel();p.context=null;p.privateDraft=false;p.task.setSelection(mode);p.input.setText(message);p.send.performClick();});await(()->panel().actionChoices.getChildCount()>0,"Local command shortcut ready");ui(()->check(panel().pending.isEmpty()&&panel().assistant.active.isEmpty(),"Local command never requests an AI model"));}
    void action(String label)throws Exception{ui(()->{View button=TenSmoke.description(panel(),"Nota action: "+label);check(button!=null,"Named action exists: "+label);button.performClick();});}
    void commands()throws Exception{
        ui(()->{DesktopWindow browser=windows().get("@browser");if(browser!=null)browser.closeWindow();DesktopWindow calculator=windows().get("@gadget:calculator");if(calculator!=null)calculator.closeWindow();home.open("@nota");windows().get("@nota").maximize();TenNotaPanel p=panel();p.context(new TenNotaContext("Previous writing","A passage",false));p.task.setSelection(4);TenSmoke.description(p,"New chat").performClick();check(p.task.getSelectedItemPosition()==0&&p.context==null,"New chat restores default command-capable Write mode");});ask("Can you open Nth Browser?",0);ui(()->check(!windows().containsKey("@browser"),"Proposal does not launch before its button is tapped"));shot("ten8-nota-shortcut");action("Open Nth Browser");await(()->windows().get("@browser")!=null,"Action opens real Nth Browser");
        ask("Open Themes");action("Open Themes settings");await(()->((TenSettings)windows().get("@settings").body).page.equals("themes"),"Action navigates actual Settings");
        AtomicReference<Intent> wifi=new AtomicReference<>();ActivityMonitor monitor=new ActivityMonitor(){@Override public ActivityResult onStartActivity(Intent intent){if(Settings.ACTION_WIFI_SETTINGS.equals(intent.getAction())){wifi.set(intent);return new ActivityResult(Activity.RESULT_CANCELED,null);}return null;}};addMonitor(monitor);try{ask("Open Wi-Fi settings");action("Open Wi-Fi settings");check(wifi.get()!=null,"Correct Android settings intent is dispatched");}finally{removeMonitor(monitor);}
        ui(()->{home.open("@nota");View suggestion=TenSmoke.description(panel(),"Try command: What can you do?");check(suggestion!=null,"Capabilities suggestion is present");suggestion.performClick();check(panel().input.getText().toString().equals("What can you do?")&&panel().actionChoices.getChildCount()==0,"Suggestion fills an editable composer without executing");panel().send.performClick();check(panel().actionChoices.getChildCount()>=3,"Help shows usable named actions");});shot("ten8-nota-capabilities");
        ui(()->{TenNotaPanel p=panel();p.input.setText("Open Calculator");p.send.performClick();p.input.setText("A changed message");check(p.actionChoices.getChildCount()==0,"Editing removes stale action buttons");p.context(new TenNotaContext("Imported note","Open Calculator",true));p.task.setSelection(0);p.send.performClick();check(p.actionChoices.getChildCount()==0,"Imported passage cannot become a command");if(!p.pending.isEmpty())p.assistant.cancel(p.pending);p.pending="synthetic_reply";try{p.result(new JSONObject().put("id","synthetic_reply").put("text","Open Calculator").put("local",true));check(p.actionChoices.getChildCount()==0&&!windows().containsKey("@gadget:calculator"),"Generated reply cannot become a command");check(!new JSONObject(p.cloud.state()).optBoolean("allowed"),"Local controls preserve cloud opt-out");}catch(JSONException e){throw new RuntimeException(e);}p.context=null;p.privateDraft=false;});
        await(()->home.notaAppTargets().stream().anyMatch(a->a.title.equals("Task switch probe")),"Installed fixture app discovered by launcher");ask("Open Task switch probe");action("Open Task switch probe");awaitSystem("Task probe note");shell("am start -n com.nthexperience.desktop.ten/com.nthexperience.desktop.MainActivity");await(()->root.isShown(),"Launcher returns from installed app");
        final String[] before={""};final int[] count={0};ui(()->{before[0]=desks().current();count[0]=desks().desks.size();});ask("Create a new desktop");action("Create new desktop");ui(()->{check(desks().desks.size()==count[0]+1&&!desks().current().equals(before[0])&&store.desktop().isEmpty(),"New desktop is an empty canvas");desks().select(before[0]);});
        ui(()->{home.open("@settings");DesktopWindow w=windows().get("@settings");w.arrange(0,0,Aero.dp(home,320),Aero.dp(home,400));TenSettings s=(TenSettings)w.body;s.navigate("colors");store.prefs.edit().putBoolean("ten_apps_dark",true).apply();home.applyTenAppearance();});await(()->((TenSettings)windows().get("@settings").body).getWidth()<=Aero.dp(home,320),"Narrow Settings measured");ui(()->{TenSettings s=(TenSettings)windows().get("@settings").body;check(s.nav.getVisibility()==View.VISIBLE&&s.scroll.getVisibility()==View.VISIBLE&&s.side.getHeight()>=s.nav.getHeight(),"Narrow dark window keeps both panes and full-height gray");});shot("ten8-settings-narrow-dark");
    }
    void shell(String cmd)throws Exception{try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(getUiAutomation().executeShellCommand(cmd))){byte[] bytes=new byte[1024];while(in.read(bytes)!=-1){}}}
}
